use std::collections::{BTreeMap,BTreeSet,HashMap};
use std::env;
use std::time::Instant;
const SETTINGS:[(u64,u64);5]=[(5,6),(3,4),(7,10),(2,3),(3,5)];
#[derive(Clone)]struct Edge{grade:usize,shell:usize,scale:usize,source:usize,target:usize,p:usize,q:usize}
fn pow(mut a:u64,mut n:u64,p:u64)->u64{let mut r=1;while n>0{if n&1==1{r=((r as u128*a as u128)%p as u128)as u64;}a=((a as u128*a as u128)%p as u128)as u64;n>>=1;}r}
fn mul(a:u64,b:u64,p:u64)->u64{((a as u128*b as u128)%p as u128)as u64}
fn primes(n:usize)->Vec<usize>{let mut s=vec![true;n+1];s[0]=false;s[1]=false;let mut p=2;while p*p<=n{if s[p]{let mut q=p*p;while q<=n{s[q]=false;q+=p;}}p+=1;}s.iter().enumerate().filter_map(|(i,&x)|x.then_some(i)).collect()}
fn graph(l:usize)->(Vec<Edge>,Vec<usize>){let ps=primes(l/2+2);let capacity:usize=ps.windows(2).map(|w|l/(w[0]*w[1])).sum();let mut e=Vec::with_capacity(capacity);for(j,w)in ps.windows(2).enumerate(){let(p,q)=(w[0],w[1]);for k in 1..=l/(p*q){e.push(Edge{grade:k*p*q,shell:j+1,scale:k,source:k*p,target:k*q,p,q});}}e.sort_by_key(|x|(x.grade,x.shell,x.scale));let mut set=BTreeSet::new();for x in&e{set.insert(x.source);set.insert(x.target);} (e,set.into_iter().collect())}
struct Elim{p:u64,basis:Vec<Option<BTreeMap<usize,u64>>>,rank:usize}
impl Elim{fn new(p:u64,n:usize)->Self{Self{p,basis:vec![None;n],rank:0}}fn insert(&mut self,mut row:BTreeMap<usize,u64>){loop{let Some((&lead,&factor))=row.iter().next()else{return};if self.basis[lead].is_none(){let inv=pow(factor,self.p-2,self.p);for x in row.values_mut(){*x=mul(*x,inv,self.p);}self.basis[lead]=Some(row);self.rank+=1;return;}let updates:Vec<_>=self.basis[lead].as_ref().unwrap().iter().map(|(&k,&v)|(k,v)).collect();for(k,v)in updates{let old=*row.get(&k).unwrap_or(&0);let value=(old+self.p-mul(factor,v,self.p))%self.p;if value==0{row.remove(&k);}else{row.insert(k,value);}}}}}
fn add(el:&mut Elim,inc:&[Vec<(usize,bool)>],edges:&[Edge],setting:Option<(u64,u64)>){let t=setting.map(|(a,b)|mul(a,pow(b,el.p-2,el.p),el.p));for entries in inc{let mut row=BTreeMap::new();for&(c,pos)in entries{let w=t.map_or(1,|z|pow(z,edges[c].shell as u64,el.p));row.insert(c,if pos{w}else{el.p-w});}el.insert(row);}}
fn main(){let a:Vec<String>=env::args().collect();let cutoff=a.get(1).and_then(|x|x.parse().ok()).unwrap_or(3318315);let modulus=a.get(2).and_then(|x|x.parse().ok()).unwrap_or(1000000007);let max_settings=a.get(3).and_then(|x|x.parse().ok()).unwrap_or(0);let start=Instant::now();let(edges,vertices)=graph(cutoff);let grade:Vec<_>=edges.iter().filter(|e|e.grade==cutoff).map(|e|(e.shell,e.scale,e.source,e.target,e.p,e.q)).collect();println!("graph cutoff={cutoff} edges={} vertices={} grade_edges={:?} elapsed_ms={}",edges.len(),vertices.len(),grade,start.elapsed().as_millis());if max_settings==0{return}let vi:HashMap<_,_>=vertices.iter().enumerate().map(|(i,&v)|(v,i)).collect();let mut inc=vec![Vec::new();vertices.len()];for(c,e)in edges.iter().enumerate(){inc[vi[&e.source]].push((c,false));inc[vi[&e.target]].push((c,true));}let mut el=Elim::new(modulus,edges.len());add(&mut el,&inc,&edges,None);println!("rank cutoff={cutoff} modulus={modulus} evaluations=1 rank={} deficiency={} elapsed_ms={}",el.rank,edges.len()-el.rank,start.elapsed().as_millis());for(i,&setting)in SETTINGS.iter().take(max_settings).enumerate(){add(&mut el,&inc,&edges,Some(setting));println!("rank cutoff={cutoff} modulus={modulus} modulated={} evaluations={} rank={} deficiency={} elapsed_ms={}",i+1,i+2,el.rank,edges.len()-el.rank,start.elapsed().as_millis());}}
